-- Estructura de tabla para `anios_lectivos`
DROP TABLE IF EXISTS `anios_lectivos`;
CREATE TABLE `anios_lectivos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `anio` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descripcion` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `anio` (`anio`),
  KEY `ix_anios_lectivos_id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

