-- Estructura de tabla para `institucion_config`
DROP TABLE IF EXISTS `institucion_config`;
CREATE TABLE `institucion_config` (
  `id` int NOT NULL,
  `nombre` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_mined` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `anio_lectivo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `regimen` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `director_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `direccion` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

