-- Estructura de tabla para `periodos_escolares`
DROP TABLE IF EXISTS `periodos_escolares`;
CREATE TABLE `periodos_escolares` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `anio_lectivo_id` int NOT NULL,
  `estado` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `anio_lectivo_id` (`anio_lectivo_id`),
  KEY `ix_periodos_escolares_id` (`id`),
  CONSTRAINT `periodos_escolares_ibfk_1` FOREIGN KEY (`anio_lectivo_id`) REFERENCES `anios_lectivos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

