-- Estructura de tabla para `grados_secciones`
DROP TABLE IF EXISTS `grados_secciones`;
CREATE TABLE `grados_secciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `grado` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `seccion` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `anio_lectivo` int NOT NULL,
  `aula_base_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_grado_seccion` (`grado`,`seccion`,`anio_lectivo`),
  UNIQUE KEY `uk_aula_base_anio` (`aula_base_id`,`anio_lectivo`),
  CONSTRAINT `fk_grados_secciones_aula_base` FOREIGN KEY (`aula_base_id`) REFERENCES `aulas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

