-- Estructura de tabla para `materias`
DROP TABLE IF EXISTS `materias`;
CREATE TABLE `materias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre_materia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Volcado de datos para la tabla `materias`
INSERT INTO `materias` (`id`, `nombre_materia`, `descripcion`) VALUES
(1, 'Matemáticas', 'Álgebra, geometría, aritmética y cálculo aplicado'),
(2, 'Lenguaje y Literatura', 'Lectura comprensiva, gramática y redacción'),
(3, 'Ciencias Naturales', 'Biología, física, química y ecología'),
(4, 'Estudios Sociales', 'Historia de El Salvador, geografía y sociedad'),
(5, 'Educación Física', 'Deportes, acondicionamiento físico y salud'),
(6, 'Moral y Cívica', 'Formación ciudadana, valores y ética'),
(7, 'Ortografía y Caligrafía', 'Escritura correcta, trazo y motricidad fina'),
(8, 'Inglés', 'Comprensión lectora, gramática y conversación'),
(9, 'Informática y Robótica', 'Computación básica, ofimática y programación'),
(10, 'Educación Artística', 'Expresión plástica, dibujo, música y arte'),
(11, 'Programacion informatica II', 'Programación e Informática'),
(12, 'Robótica Educativa', 'Taller práctico');

-- Estructura de tabla para `cargas_academicas`
DROP TABLE IF EXISTS `cargas_academicas`;
CREATE TABLE `cargas_academicas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `profesor_id` int NOT NULL,
  `materia_id` int NOT NULL,
  `grado_seccion_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `profesor_id` (`profesor_id`),
  KEY `materia_id` (`materia_id`),
  KEY `grado_seccion_id` (`grado_seccion_id`),
  CONSTRAINT `cargas_academicas_ibfk_1` FOREIGN KEY (`profesor_id`) REFERENCES `profesores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cargas_academicas_ibfk_2` FOREIGN KEY (`materia_id`) REFERENCES `materias` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cargas_academicas_ibfk_3` FOREIGN KEY (`grado_seccion_id`) REFERENCES `grados_secciones` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

