-- Estructura de tabla para `asignaturas`
DROP TABLE IF EXISTS `asignaturas`;
CREATE TABLE `asignaturas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grado_seccion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'General',
  `profesor_nombre` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'Sin asignar',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_asignaturas_codigo` (`codigo`),
  KEY `ix_asignaturas_id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

