-- Estructura de tabla para `calificaciones`
DROP TABLE IF EXISTS `calificaciones`;
CREATE TABLE `calificaciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `estudiante_id` int NOT NULL,
  `asignatura_id` int NOT NULL,
  `periodo_id` int NOT NULL,
  `nota` float NOT NULL,
  `tipo_evaluacion` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'Actividad 1: Examen Parcial',
  PRIMARY KEY (`id`),
  KEY `estudiante_id` (`estudiante_id`),
  KEY `asignatura_id` (`asignatura_id`),
  KEY `periodo_id` (`periodo_id`),
  KEY `ix_calificaciones_id` (`id`),
  CONSTRAINT `calificaciones_ibfk_1` FOREIGN KEY (`estudiante_id`) REFERENCES `estudiantes` (`id`),
  CONSTRAINT `calificaciones_ibfk_2` FOREIGN KEY (`asignatura_id`) REFERENCES `asignaturas` (`id`),
  CONSTRAINT `calificaciones_ibfk_3` FOREIGN KEY (`periodo_id`) REFERENCES `periodos_escolares` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5677 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

