-- Estructura de tabla para `horarios`
DROP TABLE IF EXISTS `horarios`;
CREATE TABLE `horarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `grado_seccion_id` int NOT NULL,
  `materia_id` int NOT NULL,
  `profesor_id` int NOT NULL,
  `anio_lectivo_id` int NOT NULL,
  `dia_semana` enum('Lunes','Martes','Miercoles','Jueves','Viernes','Sabado') COLLATE utf8mb4_unicode_ci NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  `aula_especial_id` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_docente_bloque_horario` (`profesor_id`,`dia_semana`,`hora_inicio`,`hora_fin`,`anio_lectivo_id`),
  UNIQUE KEY `uk_seccion_bloque_horario` (`grado_seccion_id`,`dia_semana`,`hora_inicio`,`hora_fin`,`anio_lectivo_id`),
  UNIQUE KEY `uk_aula_especial_bloque` (`aula_especial_id`,`dia_semana`,`hora_inicio`,`hora_fin`,`anio_lectivo_id`),
  KEY `fk_horarios_anio_lectivo` (`anio_lectivo_id`),
  KEY `fk_horarios_asignatura` (`materia_id`),
  CONSTRAINT `fk_horarios_anio_lectivo` FOREIGN KEY (`anio_lectivo_id`) REFERENCES `anios_lectivos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_horarios_asignatura` FOREIGN KEY (`materia_id`) REFERENCES `asignaturas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_horarios_aula_especial` FOREIGN KEY (`aula_especial_id`) REFERENCES `aulas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_horarios_grado_seccion` FOREIGN KEY (`grado_seccion_id`) REFERENCES `grados_secciones` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_horarios_profesor` FOREIGN KEY (`profesor_id`) REFERENCES `profesores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=421 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

